duration_units = {
    'second': 1, 'seconds': 1, 'sec': 1, 'secs': 1,
    'minute': 60, 'minutes': 60, 'min': 60, 'mins': 60,
    'hour': 3600, 'hours': 3600, 'hr': 3600, 'hrs': 3600,
}
def duration_seconds_in_line(line):
    cleaned = line.lower()
    for character in ',;()[]{}:!?/\\-':
        cleaned = cleaned.replace(character, ' ')
    tokens = cleaned.split()
    total = 0
    for index in range(len(tokens) - 1):
        number_text = tokens[index].strip('.')
        unit_text = tokens[index + 1].strip('.')
        if unit_text in duration_units:
            try:
                total += int(float(number_text) * duration_units[unit_text])
            except ValueError:
                pass
    return total

duration_lines = []
for line in workout_note['content'].splitlines():
    line_seconds = duration_seconds_in_line(line)
    if line_seconds > 0:
        duration_lines.append({'line': line, 'seconds': line_seconds})
explicit_duration_lines = [item for item in duration_lines if any(marker in item['line'].lower() for marker in ('total', 'duration', 'lasts', 'will last'))]
if explicit_duration_lines:
    workout_duration_seconds = max(item['seconds'] for item in explicit_duration_lines)
else:
    workout_duration_seconds = sum(item['seconds'] for item in duration_lines)
if workout_duration_seconds <= 0:
